node --input-type=module <<'NODE'
import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import {spawnSync} from 'node:child_process';
const tempRoot=fs.mkdtempSync(path.join(os.tmpdir(),'media-v411-packet-'));
console.log('[owned-temp] '+tempRoot);
const result=spawnSync('bash',['scripts/internal/verify_recording_frame_correlation.sh'],{
 env:{...process.env,TMPDIR:tempRoot,MEDIA_SERVER_GST_CACHE_DIR:path.join(tempRoot,'gst-cache'),
 GST_REGISTRY_1_0:path.join(tempRoot,'registry.bin'),GST_REGISTRY:path.join(tempRoot,'registry.bin')},
 encoding:'utf8',maxBuffer:8*1024*1024,timeout:60000
});
process.stdout.write(result.stdout||'');process.stderr.write(result.stderr||'');
if(result.error||result.signal){console.log('[cleanup] retained; child completion uncertain '+JSON.stringify({code:result.error?.code,signal:result.signal}));process.exitCode=1;}
else {
 if(!path.basename(tempRoot).startsWith('media-v411-packet-')||fs.lstatSync(tempRoot).isSymbolicLink())throw Error('owned temp mismatch');
 fs.rmSync(tempRoot,{recursive:true});
 console.log('[cleanup] '+JSON.stringify({path:tempRoot,removed:!fs.existsSync(tempRoot),scope:'owned compile/GStreamer cache only'}));
 process.exitCode=result.status??1;
}
NODE
